import os
import random
import time
import base64

# Target: Generate valid JSON bytes suitable for:
# - cupsJSONImportFile(path): expects a JSON document
# - cupsJWTLoadCredentials(path, common_name): expects a credentials/key bundle in JSON
# The fuzzer supplies the filename pointing to our buffer; we only need to return the
# file contents as bytes. Keep size <= 4096 bytes.
#
# We produce a variety of valid JSON documents:
# - Simple scalars (null, true, false, numbers, strings)
# - Arrays/objects with nested structures
# - Credential/keyset-like JSON (JWK/JWK Set, PEM-like fields)
# - JWT-like container with header/payload/signature fields
# - Mixed objects containing fields that may be probed by JWT loaders
#
# All outputs are valid JSON, intentionally non-malformed.

MAX_BYTES = 4096

WORDS = [
    "print", "cups", "json", "token", "jwt", "key", "printer", "job",
    "user", "admin", "secure", "test", "alpha", "beta", "gamma",
    "device", "network", "dnssd", "ipp", "media", "page", "color"
]

ALGOS = [
    "none", "HS256", "HS384", "HS512", "RS256", "RS384", "RS512",
    "ES256", "ES384", "ES512"
]

KTY_VALUES = ["oct", "RSA", "EC"]
CRV_VALUES = ["P-256", "P-384", "P-521"]


def _randstr(rng: random.Random, min_len=0, max_len=24):
    n = rng.randint(min_len, max_len)
    # Use a mix of words and random chars to keep JSON readable but varied
    parts = []
    while len("".join(parts)) < n:
        if rng.random() < 0.6:
            parts.append(rng.choice(WORDS))
        else:
            parts.append(chr(rng.randint(32, 126)))
    s = "".join(parts)[:n]
    return s


def _b64url_random(rng: random.Random, nbytes: int) -> str:
    raw = bytes(rng.getrandbits(8) for _ in range(nbytes))
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _make_scalar(rng: random.Random):
    choice = rng.randint(0, 5)
    if choice == 0:
        return None
    if choice == 1:
        return True
    if choice == 2:
        return False
    if choice == 3:
        # number
        if rng.random() < 0.5:
            return rng.randint(-2**31, 2**31 - 1)
        else:
            return float(rng.randint(-100000, 100000)) / max(1, rng.randint(1, 997))
    if choice == 4:
        return _randstr(rng, 0, 40)
    # small array
    return [ _make_scalar(rng) for _ in range(rng.randint(0, 5)) ]


def _make_generic_object(rng: random.Random, depth=0):
    obj = {}
    # A few generic fields
    obj["type"] = rng.choice(["object", "array", "string", "number", "boolean", "null"])  # may be useful for cupsJSONGetType
    obj["time"] = int(time.time())
    obj["title"] = _randstr(rng, 3, 20)
    obj["version"] = f"{rng.randint(0,3)}.{rng.randint(0,9)}.{rng.randint(0,9)}"
    # Nested content
    if depth < 2:
        for i in range(rng.randint(1, 5)):
            key = _randstr(rng, 3, 12)
            if rng.random() < 0.4:
                obj[key] = _make_scalar(rng)
            elif rng.random() < 0.7:
                obj[key] = [ _make_scalar(rng) for _ in range(rng.randint(0, 6)) ]
            else:
                obj[key] = _make_generic_object(rng, depth + 1)
    return obj


def _make_jwk_oct(rng: random.Random):
    return {
        "kty": "oct",
        "k": _b64url_random(rng, rng.randint(16, 64)),
        "alg": rng.choice(ALGOS),
        "kid": _randstr(rng, 4, 16),
        "use": rng.choice(["sig", "enc"]) if rng.random() < 0.7 else None
    }


def _make_jwk_rsa(rng: random.Random):
    # Minimal RSA JWK fields
    return {
        "kty": "RSA",
        "n": _b64url_random(rng, rng.randint(128, 512)),
        "e": _b64url_random(rng, 3),
        # Optionally include private components
        **({} if rng.random() < 0.5 else {
            "d": _b64url_random(rng, rng.randint(128, 512)),
        }),
        "alg": rng.choice([a for a in ALGOS if a.startswith("RS")]),
        "kid": _randstr(rng, 4, 16)
    }


def _make_jwk_ec(rng: random.Random):
    return {
        "kty": "EC",
        "crv": rng.choice(CRV_VALUES),
        "x": _b64url_random(rng, rng.randint(32, 66)),
        "y": _b64url_random(rng, rng.randint(32, 66)),
        **({} if rng.random() < 0.5 else {
            "d": _b64url_random(rng, rng.randint(32, 66)),
        }),
        "alg": rng.choice([a for a in ALGOS if a.startswith("ES")]),
        "kid": _randstr(rng, 4, 16)
    }


def _make_jwk(rng: random.Random):
    kty = rng.choice(KTY_VALUES)
    if kty == "oct":
        return _make_jwk_oct(rng)
    if kty == "RSA":
        return _make_jwk_rsa(rng)
    return _make_jwk_ec(rng)


def _make_jwks(rng: random.Random):
    return {
        "keys": [ _make_jwk(rng) for _ in range(rng.randint(1, 4)) ]
    }


def _make_pem_bundle_like(rng: random.Random):
    # JSON-wrapped PEM-like strings; some loaders accept this style.
    def pem(label: str, nbytes: int) -> str:
        b = bytes(rng.getrandbits(8) for _ in range(nbytes))
        body = base64.encodebytes(b).decode("ascii").replace("\n", "\n")
        return f"-----BEGIN {label}-----\n{body}-----END {label}-----\n"
    bundle = {
        "private_key_pem": pem("PRIVATE KEY", rng.randint(512, 2048)),
        "certificate_pem": pem("CERTIFICATE", rng.randint(512, 2048)),
        "chain": [pem("CERTIFICATE", rng.randint(256, 1024)) for _ in range(rng.randint(0, 2))],
        "algorithm": rng.choice(ALGOS),
        "common_name": _randstr(rng, 3, 24)
    }
    return bundle


def _make_jwt_like(rng: random.Random):
    header = {
        "alg": rng.choice(ALGOS),
        "typ": rng.choice(["JWT", "JWS"]),
        "kid": _randstr(rng, 4, 12)
    }
    payload = {
        "iss": _randstr(rng, 3, 18),
        "sub": _randstr(rng, 3, 18),
        "aud": _randstr(rng, 3, 18),
        "iat": int(time.time()) - rng.randint(0, 100000),
        "exp": int(time.time()) + rng.randint(60, 100000),
        "scope": rng.choice(["print", "manage", "all"]) if rng.random() < 0.7 else _randstr(rng, 3, 20)
    }
    # Construct compact form string (not validated cryptographically)
    def enc(obj):
        import json
        return _b64url_random(rng, rng.randint(8, 24)) if rng.random() < 0.2 else base64.urlsafe_b64encode(
            json.dumps(obj, separators=(",", ":")).encode("utf-8")
        ).rstrip(b"=").decode("ascii")

    compact = f"{enc(header)}.{enc(payload)}.{_b64url_random(rng, rng.randint(8, 64))}"
    return {
        "format": rng.choice(["compact", "json"]),
        "header": header,
        "payload": payload,
        "signature": _b64url_random(rng, rng.randint(16, 64)),
        "token": compact
    }


def _select_document(rng: random.Random):
    choice = rng.random()
    if choice < 0.12:
        # Simple scalar JSON
        return _make_scalar(rng)
    if choice < 0.34:
        # Generic nested object
        return _make_generic_object(rng)
    if choice < 0.58:
        # JWK Set
        obj = _make_jwks(rng)
        # Optionally annotate with typical fields some loaders may expect
        if rng.random() < 0.5:
            obj["iss"] = _randstr(rng, 3, 18)
            obj["cn"] = _randstr(rng, 3, 18)
        return obj
    if choice < 0.78:
        # PEM-like bundle
        return _make_pem_bundle_like(rng)
    else:
        # JWT-like container possibly with keys alongside
        doc = _make_jwt_like(rng)
        if rng.random() < 0.7:
            doc["keys"] = _make_jwks(rng)["keys"]
        return doc


def _to_json_bytes(obj) -> bytes:
    import json
    # Use compact separators to keep size small
    data = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
    b = data.encode("utf-8")
    # Ensure size cap; if too large, fall back to a minimal JWKS with 1 oct key
    if len(b) > MAX_BYTES:
        minimal = {"keys": [{"kty": "oct", "k": base64.urlsafe_b64encode(b"k").decode("ascii")}]} 
        b = json.dumps(minimal, separators=(",", ":")).encode("utf-8")
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    doc = _select_document(rng)
    return _to_json_bytes(doc)

import random
import base64
import json
from typing import List, Tuple

# This generator focuses on producing valid UTF-8 JSON strings that are interesting for:
# - cupsJSONImportString: expects any valid JSON text
# - cupsJWTImportString: expects a JWS/JWT string (Compact or JSON Serialization)
# The fuzzer uses the same FUZZ_PARAM_STR source for both stubs, so we bias generation
# toward valid JWS inputs while also mixing in diverse valid JSON documents. All outputs
# are valid UTF-8 and <= 4096 bytes.

# Utility: base64url encode without padding
def b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode('ascii').rstrip('=')

# Utility: deterministic random JSON value tree
def rand_json_value(rng: random.Random, depth: int = 0) -> object:
    # Limit depth to avoid recursion blowups
    if depth > 3:
        choices = ['str', 'num', 'bool', 'null']
    else:
        choices = ['obj', 'arr', 'str', 'num', 'bool', 'null']
    t = rng.choice(choices)
    if t == 'obj':
        obj = {}
        for _ in range(rng.randint(0, 6)):
            key = rand_json_string(rng)
            obj[key] = rand_json_value(rng, depth + 1)
        return obj
    if t == 'arr':
        return [rand_json_value(rng, depth + 1) for _ in range(rng.randint(0, 8))]
    if t == 'str':
        return rand_json_texty_string(rng)
    if t == 'num':
        # Mix ints and floats, including boundary-ish values
        if rng.random() < 0.5:
            return rng.choice([0, 1, -1, 2**31-1, -2**31, 2**53-1, -2**53+1, rng.randint(-10**9, 10**9)])
        else:
            sign = -1 if rng.random() < 0.5 else 1
            mant = rng.uniform(0, 1e6)
            exp = rng.randint(-10, 10)
            return sign * mant * (10 ** exp)
    if t == 'bool':
        return bool(rng.getrandbits(1))
    return None

def rand_json_string(rng: random.Random) -> str:
    # Keys: ASCII safe plus some unicode
    parts = []
    length = rng.randint(1, 16)
    for _ in range(length):
        ctype = rng.randint(0, 9)
        if ctype < 6:
            parts.append(chr(rng.randint(0x61, 0x7a)))  # a-z
        elif ctype < 8:
            parts.append(chr(rng.randint(0x30, 0x39)))  # 0-9
        elif ctype == 8:
            parts.append(rng.choice(['_', '-', '.', ':']))
        else:
            parts.append(chr(rng.choice([0x00E9, 0x00F1, 0x0101, 0x03B1, 0x0416])))
    return ''.join(parts)

def rand_json_texty_string(rng: random.Random) -> str:
    # Produce strings with escapes and unicode
    s = []
    length = rng.randint(0, 64)
    for _ in range(length):
        p = rng.random()
        if p < 0.6:
            s.append(chr(rng.randint(32, 126)))  # printable ASCII
        elif p < 0.8:
            s.append(chr(rng.choice([0x00E9, 0x00F1, 0x0101, 0x03C0, 0x221E, 0x20AC])))
        else:
            s.append(rng.choice(['\"', '\\', '\n', '\t']))
    return ''.join(s)

# JWT/JWS Compact Serialization generator (valid structure, with or without signature)
# header.payload.signature where each is base64url

def make_jws_compact(rng: random.Random) -> str:
    # Header
    algs = [
        'none',  # allow unsigned
        'HS256', 'HS384', 'HS512',
        'RS256', 'RS384', 'RS512',
        'ES256', 'ES384', 'ES512',
    ]
    hdr = {
        'typ': rng.choice(['JWT', 'JOSE', 'JWS']),
        'alg': rng.choice(algs)
    }
    # Sometimes include kid/cty
    if rng.random() < 0.5:
        hdr['kid'] = rand_json_string(rng)
    if rng.random() < 0.3:
        hdr['cty'] = rng.choice(['JWT', 'application/json'])

    # Payload claims: valid JSON object
    payload = {
        'iss': rng.choice(['cups', 'test', 'printer', 'user', 'admin']),
        'sub': rand_json_string(rng),
        'aud': rng.choice(['cups', 'urn:printer', 'https://example.org/print']),
    }
    # Numeric date claims
    now = rng.randint(1600000000, 2000000000)
    if rng.random() < 0.8:
        payload['iat'] = now
    if rng.random() < 0.8:
        payload['exp'] = now + rng.randint(60, 86400)
    if rng.random() < 0.5:
        payload['nbf'] = now - rng.randint(0, 3600)
    # Additional custom claims
    for k in rng.sample(['name', 'scope', 'roles', 'admin', 'features'], rng.randint(0, 3)):
        if k == 'name':
            payload[k] = rand_json_texty_string(rng)
        elif k == 'scope':
            payload[k] = ' '.join(rng.sample(['print', 'scan', 'admin', 'read', 'write'], rng.randint(1, 3)))
        elif k == 'roles':
            payload[k] = rng.sample(['user', 'admin', 'operator'], rng.randint(1, 2))
        elif k == 'admin':
            payload[k] = bool(rng.getrandbits(1))
        elif k == 'features':
            payload[k] = {'duplex': True, 'color': bool(rng.getrandbits(1))}

    header_b64 = b64url(json.dumps(hdr, separators=(',', ':'), ensure_ascii=False).encode('utf-8'))
    payload_b64 = b64url(json.dumps(payload, separators=(',', ':'), ensure_ascii=False).encode('utf-8'))

    if hdr['alg'] == 'none':
        sig = ''
    else:
        # Produce a deterministic-looking but arbitrary signature bytes
        sig_bytes = rng.randbytes(rng.randint(16, 64)) if hasattr(rng, 'randbytes') else bytes([rng.randrange(256) for _ in range(rng.randint(16, 64))])
        sig = b64url(sig_bytes)

    return f"{header_b64}.{payload_b64}.{sig}"

# JWS JSON Serialization generator
# {"payload":"b64url(..)","protected":"b64url(hdr)","signature":"b64url(sig)"}

def make_jws_json(rng: random.Random) -> str:
    hdr = {
        'alg': rng.choice(['HS256', 'RS256', 'ES256', 'none']),
        'typ': 'JWT'
    }
    if rng.random() < 0.5:
        hdr['kid'] = rand_json_string(rng)

    payload_obj = {}
    # Create an interesting nested JSON payload
    payload_obj['data'] = {
        'array': [rand_json_value(rng, 1) for _ in range(rng.randint(1, 5))],
        'meta': {'version': rng.randint(1, 3), 'ok': True}
    }

    protected_b64 = b64url(json.dumps(hdr, separators=(',', ':'), ensure_ascii=False).encode('utf-8'))
    payload_b64 = b64url(json.dumps(payload_obj, separators=(',', ':'), ensure_ascii=False).encode('utf-8'))

    if hdr['alg'] == 'none':
        sig = ''
    else:
        sig_bytes = rng.randbytes(rng.randint(16, 64)) if hasattr(rng, 'randbytes') else bytes([rng.randrange(256) for _ in range(rng.randint(16, 64))])
        sig = b64url(sig_bytes)

    obj = {
        'payload': payload_b64,
        'protected': protected_b64,
        'signature': sig
    }

    # Occasionally use the General JSON Serialization with signatures array
    if rng.random() < 0.3:
        obj = {
            'payload': payload_b64,
            'signatures': [
                {'protected': protected_b64, 'signature': sig},
                # sometimes add a second signature entry
            ]
        }
        if rng.random() < 0.5:
            hdr2 = {'alg': 'HS384'}
            obj['signatures'].append({'protected': b64url(json.dumps(hdr2).encode('utf-8')), 'signature': sig})

    return json.dumps(obj, ensure_ascii=False, separators=(',', ':'))

# General JSON document (non-JWT) generator

def make_general_json(rng: random.Random) -> str:
    # Compose an object with mixed types, arrays, and nested objects
    doc = {
        'menu': {
            'id': rand_json_string(rng),
            'value': rand_json_texty_string(rng),
            'popup': {
                'items': [
                    {'value': rand_json_string(rng), 'onclick': 'Close()'},
                    {'value': 'Open', 'onclick': 'Open()'},
                    {'value': 'Print', 'onclick': 'Print()'}
                ]
            }
        },
        'numbers': [rng.randint(-5, 5), rng.uniform(-1e3, 1e3), 0, 1, 2**31-1],
        'flags': {'duplex': True, 'color': False, 'mirror': bool(rng.getrandbits(1))},
        'nested': rand_json_value(rng, 0)
    }
    # Sometimes choose an array or a primitive top-level to diversify
    choice = rng.random()
    if choice < 0.2:
        return json.dumps([rand_json_value(rng, 0) for _ in range(rng.randint(1, 6))], ensure_ascii=False)
    elif choice < 0.3:
        return json.dumps(rand_json_value(rng, 0), ensure_ascii=False)
    else:
        return json.dumps(doc, ensure_ascii=False)

# High-level generator: choose among JWT Compact, JWS JSON, and general JSON

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    pick = rng.random()
    if pick < 0.45:
        s = make_jws_compact(rng)
    elif pick < 0.70:
        s = make_jws_json(rng)
    else:
        s = make_general_json(rng)

    data = s.encode('utf-8')
    # Ensure max size bound
    if len(data) > 4096:
        data = data[:4096]
    return data
